@@ -0,0 +1,99 @@
+import {Buffer} from 'node:buffer';
+import {promisify} from 'node:util';
+import is from '@sindresorhus/is';
+import isFormData from './core/utils/is-form-data.js';
+
+export type UploadBudgetHeaders = Record<string, string | string[] | number | undefined>;
+
+export type UploadBudget = {
+	/**
+	The upload size in bytes, or `undefined` when it cannot be known without consuming the body.
+	*/
+	bytes: number | undefined;
+
+	/**
+	Whether the upload fits within the limit, or `null` when the size is unknown.
+	*/
+	fits: boolean | null; // eslint-disable-line @typescript-eslint/ban-types
+};
+
+const getContentLength = (headers: UploadBudgetHeaders | undefined): number | undefined => {
+	if (!headers) {
+		return undefined;
+	}
+
+	for (const [name, value] of Object.entries(headers)) {
+		if (name.toLowerCase() !== 'content-length' || value === undefined) {
+			continue;
+		}
+
+		const rawValue = String(Array.isArray(value) ? value[0] : value).trim();
+
+		if (/^\d+$/.test(rawValue)) {
+			const length = Number(rawValue);
+
+			if (Number.isSafeInteger(length)) {
+				return length;
+			}
+		}
+	}
+
+	return undefined;
+};
+
+const getKnownBodySize = async (body: unknown): Promise<number | undefined> => {
+	if (body === undefined || body === null) {
+		return 0;
+	}
+
+	if (is.string(body)) {
+		return Buffer.byteLength(body, 'utf8');
+	}
+
+	if (is.arrayBuffer(body) || is.sharedArrayBuffer(body) || ArrayBuffer.isView(body)) {
+		return body.byteLength;
+	}
+
+	if (is.blob(body)) {
+		return body.size;
+	}
+
+	// The legacy `form-data` package can compute its length without reading the stream.
+	if (isFormData(body)) {
+		try {
+			return await promisify(body.getLength.bind(body))();
+		} catch {
+			return undefined;
+		}
+	}
+
+	return undefined;
+};
+
+/**
+Determine whether an upload fits within a byte budget, without opening a connection or consuming the body.
+
+An explicit `content-length` header takes priority over the body. Strings are measured in UTF-8 bytes and a missing body counts as zero bytes. Streams, iterables and other bodies whose size cannot be determined without reading them result in `fits: null`.
+
+@param body - The request body.
+@param headers - The request headers.
+@param limit - The maximum number of bytes allowed.
+*/
+export async function uploadFits(body: unknown, headers: UploadBudgetHeaders | undefined, limit: number): Promise<UploadBudget> {
+	if (typeof limit !== 'number') {
+		throw new TypeError(`Expected \`limit\` to be a number, got ${typeof limit}`);
+	}
+
+	if (!Number.isFinite(limit) || limit < 0) {
+		throw new RangeError(`Expected \`limit\` to be a finite non-negative number, got ${limit}`);
+	}
+
+	const bytes = getContentLength(headers) ?? await getKnownBodySize(body);
+
+	return {
+		bytes,
+		fits: bytes === undefined ? null : bytes <= limit,
+	};
+}
+
+export default uploadFits;
diff --git a/test/upload-budget.ts b/test/upload-budget.ts
new file mode 100644
index 0000000..0c0d362
--- /dev/null
+++ b/test/upload-budget.ts
@@ -0,0 +1,82 @@
+import {Buffer} from 'node:buffer';
+import {Readable} from 'node:stream';
+import test from 'ava';
+import FormData from 'form-data';
+import uploadFits from '../source/upload-budget.js';
+
+test('no body is zero bytes', async t => {
+	t.deepEqual(await uploadFits(undefined, {}, 0), {bytes: 0, fits: true});
+	t.deepEqual(await uploadFits(null, undefined, 10), {bytes: 0, fits: true});
+	t.deepEqual(await uploadFits('', {}, 0), {bytes: 0, fits: true});
+});
+
+test('strings are measured in UTF-8 bytes', async t => {
+	t.deepEqual(await uploadFits('héllo', {}, 6), {bytes: 6, fits: true});
+	t.deepEqual(await uploadFits('héllo', {}, 5), {bytes: 6, fits: false});
+	t.deepEqual(await uploadFits('🦄', {}, 3), {bytes: 4, fits: false});
+});
+
+test('binary bodies', async t => {
+	t.deepEqual(await uploadFits(Buffer.alloc(8), {}, 8), {bytes: 8, fits: true});
+	t.deepEqual(await uploadFits(new Uint8Array(9), {}, 8), {bytes: 9, fits: false});
+	t.deepEqual(await uploadFits(new ArrayBuffer(3), {}, 8), {bytes: 3, fits: true});
+	t.deepEqual(await uploadFits(new Blob(['abcd']), {}, 3), {bytes: 4, fits: false});
+});
+
+test('explicit content-length takes priority', async t => {
+	t.deepEqual(await uploadFits('a', {'content-length': '100'}, 50), {bytes: 100, fits: false});
+	t.deepEqual(await uploadFits('a'.repeat(100), {'Content-Length': 10}, 50), {bytes: 10, fits: true});
+
+	const stream = Readable.from(['data']);
+	t.deepEqual(await uploadFits(stream, {'content-length': '4'}, 4), {bytes: 4, fits: true});
+});
+
+test('malformed content-length falls back to the body', async t => {
+	t.deepEqual(await uploadFits('abc', {'content-length': 'nope'}, 5), {bytes: 3, fits: true});
+	t.deepEqual(await uploadFits('abc', {'content-length': '-1'}, 5), {bytes: 3, fits: true});
+});
+
+test('streams are unknown and not consumed', async t => {
+	const stream = Readable.from(['hello']);
+	t.deepEqual(await uploadFits(stream, {}, 100), {bytes: undefined, fits: null});
+	t.false(stream.readableDidRead);
+	t.is(stream.readableFlowing, null);
+
+	const chunks: string[] = [];
+	for await (const chunk of stream) {
+		chunks.push(String(chunk));
+	}
+
+	t.deepEqual(chunks, ['hello']);
+});
+
+test('iterables are unknown', async t => {
+	async function * generate() {
+		yield 'a';
+	}
+
+	t.deepEqual(await uploadFits(generate(), {}, 100), {bytes: undefined, fits: null});
+});
+
+test('legacy form-data reports its length without being consumed', async t => {
+	const form = new FormData();
+	form.append('field', 'value');
+
+	const result = await uploadFits(form, {}, 1_000_000);
+	t.is(result.bytes, form.getLengthSync());
+	t.true(result.fits);
+});
+
+test('rejects invalid limits', async t => {
+	await t.throwsAsync(uploadFits('a', {}, -1), {instanceOf: RangeError});
+	await t.throwsAsync(uploadFits('a', {}, Number.NaN), {instanceOf: RangeError});
+	await t.throwsAsync(uploadFits('a', {}, Number.POSITIVE_INFINITY), {instanceOf: RangeError});
+	// @ts-expect-error Invalid type
+	await t.throwsAsync(uploadFits('a', {}, '10'), {instanceOf: TypeError});
+});
+
+test('invalid limits do not consume the body', async t => {
+	const stream = Readable.from(['hello']);
+	await t.throwsAsync(uploadFits(stream, {}, -1), {instanceOf: RangeError});
+	t.false(stream.readableDidRead);
+});
